#include <iostream>
#include <string>
bool ready(const std::string& name, bool accepted) {
    // One function owns the whole readiness rule.
    return !name.empty() && accepted;
}
int main() {
    std::cout << std::boolalpha;
    std::cout << ready("Mina", false) << '\n';
    std::cout << ready("Mina", true) << '\n';
    std::cout << ready("", true) << '\n';
}

#include <iostream>
#include <string>
int main() {
    std::string name;
    bool accepted = false;
    bool enabled = false;
    // Wrong: each handler replaces the combined policy.
    enabled = accepted;
    name = "Mina";
    enabled = !name.empty();
    std::cout << std::boolalpha;
    std::cout << "split handlers: " << enabled << '\n';
    enabled = !name.empty() && accepted;
    std::cout << "combined rule: " << enabled << '\n';
}
